# Check if there's any environment variable or config that indicates how to call rlm.finish
import os
env_vars = {k: v for k, v in os.environ.items() if 'rlm' in k.lower() or 'finish' in k.lower() or 'task' in k.lower()}
print("Relevant env vars:", env_vars)

# Also check if there's a .rlm directory or file
for root, dirs, files in os.walk('.'):
    for f in files:
        if 'rlm' in f.lower() or 'finish' in f.lower():
            print(f"Found: {os.path.join(root, f)}")
